"""CSV エクスポート — 計画に基づいて実装済み。"""
import fastcsv


def to_csv(summary: dict) -> str:
    rows = [["level", "count"]]
    for level, count in summary["by_level"].items():
        rows.append([level, count])
    return fastcsv.dumps(rows)

